-- Access, phase 3 (docs/plan.md §1.26 "Browser sites"): the operator's catalogue of websites agents
-- may sign in to. `browser_site` holds the slug, name, live risk tier and the operator's notes (whose
-- check of the site's terms, why the tier); `browser_site_version` holds each version of the login
-- steps and URL rules, immutable like skill versions, and a client's browser connection pins one.
-- Operator tables: no client owns a row and only operator sessions read or write them. New tables
-- only, so the previous Worker keeps working: it never reads them. Generated by drizzle-kit; the
-- grants, row-level security and trigger at the end are hand-written, as in 0011.
CREATE TABLE "browser_site" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"slug" text NOT NULL,
	"name" text NOT NULL,
	"tier" text NOT NULL,
	"notes" text DEFAULT '' NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "browser_site_slug_unique" UNIQUE("slug"),
	CONSTRAINT "browser_site_tier_check" CHECK ("browser_site"."tier" in ('low', 'medium', 'high', 'blocked')),
	CONSTRAINT "browser_site_slug_check" CHECK ("browser_site"."slug" ~ '^[a-z0-9][a-z0-9-]{0,62}$')
);
