-- DECISION: operator only, as templates are (tenant_id null and app_is_operator()), but without a
-- tenant_id column: no client ever owns a site. Runs read a connection's pinned version through an
-- operator transaction that names no client (apps/api), so no client row is visible beside it.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['browser_site', 'browser_site_version'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY operator_only ON %I FOR ALL TO PUBLIC '
      'USING (app_is_operator()) WITH CHECK (app_is_operator())', t);
  END LOOP;
END
$$;
