-- Immutable history (CLAUDE.md invariant 3): a site version never changes and is never deleted.
CREATE TRIGGER browser_site_version_immutable BEFORE UPDATE OR DELETE ON browser_site_version
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
